import hashlib
import datetime as dt


def sha256(data: str) -> str:
    return hashlib.sha256(data.encode()).hexdigest()


def utcnow() -> str:
    return dt.datetime.utcnow().isoformat()

import time
import logging

log = logging.getLogger(__name__)


def request_timer(app):
    @app.before_request
    def _start():
        from flask import g
        g.start = time.monotonic()

    @app.after_request
    def _end(response):
        from flask import g
        elapsed = time.monotonic() - g.start
        log.info("request took %.3fs", elapsed)
        return response

